function requireProvenance(context,id,kind,wave,subject) { const member=context.registryContext?.provenance.find((entry)=>entry.id===id); if (!member||kind&&member.sourceKind!==kind||wave&&member.wave!==wave||subject&&member.subject!==subject) fail('provenance registry membership drift'); return member; }
// prettier-ignore
function requireRef(context,ref,kind,targetDigest,validationProvenanceId) { const member=context.registryContext?.refs.find((entry)=>entry.ref===ref); if (!member||kind&&member.kind!==kind||targetDigest&&member.targetDigest!==targetDigest||validationProvenanceId&&member.validationProvenanceId!==validationProvenanceId) fail('ref registry membership drift'); return member; }
// prettier-ignore
function validateManifest(value, context) { sortedUnique(value.entries,(entry)=>entry.path,'manifest'); value.entries.forEach((entry)=>{ exactKeys(entry,['path','type','size','digest'],'manifest entry'); if (entry.type !== 'file' || !Number.isSafeInteger(entry.size) || entry.size < 0 || !DIGEST.test(entry.digest)) fail('invalid manifest entry'); }); if (context.expectedPaths) exactSet(value.entries.map(({path})=>path),context.expectedPaths,'manifest paths'); }
// prettier-ignore
function validateObservations(values) { sortedUnique(values,(entry)=>entry.id,'observations'); values.forEach((entry)=>{ exactKeys(entry,['id','status','failureFingerprint'],'observation'); if (!['passed','failed','missing'].includes(entry.status) || (entry.status === 'passed') !== (entry.failureFingerprint === null) || entry.failureFingerprint!==null&&!DIGEST.test(entry.failureFingerprint)) fail('observation fingerprint drift'); }); }
// prettier-ignore
function exactKeys(value, keys, label) { if (!value || typeof value !== 'object' || Array.isArray(value) || JSON.stringify(Object.keys(value)) !== JSON.stringify(keys)) fail(`${label} fields drift`); }
// prettier-ignore
function exactSet(actual, expected, label) { if (JSON.stringify([...actual].sort()) !== JSON.stringify([...expected].sort())) fail(`${label} drift`); }
// prettier-ignore
function sortedUnique(values, selector, label) { if (!Array.isArray(values)) fail(`${label} must be an array`); const ids=values.map(selector); if (new Set(ids).size !== ids.length || JSON.stringify(ids) !== JSON.stringify([...ids].sort())) fail(`${label} must be sorted and unique`); }
// prettier-ignore
function sortedKeys(value, label, valuesUnchecked=false) { if (!value || typeof value !== 'object' || Array.isArray(value) || JSON.stringify(Object.keys(value)) !== JSON.stringify(Object.keys(value).sort()) || !valuesUnchecked && Object.values(value).some((entry)=>!DIGEST.test(entry))) fail(`${label} keys drift`); }
// prettier-ignore
function bounded(value, label) { if (typeof value !== 'string' || value.length === 0 || value.length > 512 || /[\u0000-\u001f\u007f]/.test(value)) fail(`invalid ${label}`); }
// prettier-ignore
function privacy(value) { if (!value || typeof value !== 'object') return; Object.entries(value).forEach(([key,entry]) => { if (UNSAFE_KEY.test(key) || typeof entry === 'string' && UNSAFE_VALUE.test(entry)) fail('unsafe retained receipt value'); privacy(entry); }); }
// prettier-ignore
function deepFreeze(value) { Object.values(value).forEach((entry)=>{if (entry&&typeof entry==='object') deepFreeze(entry);}); return Object.freeze(value); }
// prettier-ignore
function fail(message) { throw new Error(`CAMP01_RECEIPT_INVALID: ${message}`); }
